import ChatProductCard from "./ChatProductCard";

// A single chat turn: the text bubble, plus (for assistant replies only) any
// real catalogue products chosen to go with it. `products` is a plain array
// of catalogue product objects — never HTML or markdown generated by the AI
// model — so the cards are always backed by real stored data.
export default function ChatMessage({ role, text, products = [], onAddToBasket }) {
  const isUser = role === "user";

  return (
    <div className={`flex flex-col gap-2 ${isUser ? "items-end" : "items-start"}`}>
      <div
        className={`max-w-[85%] whitespace-pre-line rounded-2xl px-3.5 py-2 text-sm leading-relaxed ${
          isUser ? "bg-emerald-600 text-white" : "bg-slate-100 text-slate-800"
        }`}
      >
        {text}
      </div>

      {!isUser && products.length > 0 && (
        <div className="flex w-full max-w-[85%] flex-col gap-2">
          {products.map((product) => (
            <ChatProductCard key={product.id} product={product} onAddToBasket={onAddToBasket} />
          ))}
        </div>
      )}
    </div>
  );
}
